import java.io.*;
import java.util.*;

public class A {
    private static List<Long> numbers, subsetSums;

    private static void generateAllSubsets(int index, long sum) {
        if (index == numbers.size()) {
            subsetSums.add(sum);
            return;
        }
        generateAllSubsets(index + 1, sum + numbers.get(index));
        generateAllSubsets(index + 1, sum);
    }

    private static boolean checkCondition(long M, long W, long x) {
        if (x == M) return true;

        long totalX = x + M;
        while (totalX > 0) {
            if (totalX % W > 1) return false;
            totalX /= W;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        long W = Long.parseLong(inputLine[0]);
        long M = Long.parseLong(inputLine[1]);

        if (W == 2) {
            System.out.println("YES");
            return;
        }

        numbers = new ArrayList<>();
        numbers.add(1L);
        numbers.add(W);

        long val = W;
        final long MAX_VAL = (long) 1e10;

        while (true) {
            val *= W;
            if (val < 0 || val > MAX_VAL) break;
            numbers.add(val);
        }

        subsetSums = new ArrayList<>();
        generateAllSubsets(0, 0);

        boolean resultFlag = false;
        for (long sumCandidate : subsetSums) {
            resultFlag |= checkCondition(M, W, sumCandidate);
            if (resultFlag) break;
        }

        System.out.println(resultFlag ? "YES" : "NO");
    }
}
